const crypto = require("crypto");

const headers = $json.headers || {};
const query = $json.query || {};

const fail = (httpStatus, error) => [{ json: { ok: false, http_status: httpStatus, error } }];

const rawExcluded = String(query.excluded_account_ids || "").trim();
if (rawExcluded && !/^\d+(,\d+)*$/.test(rawExcluded)) return fail(400, "EXCLUDED_ACCOUNT_IDS_INVALID");

const excludedIds = rawExcluded ? [...new Set(rawExcluded.split(",").map((value) => Number(value)))] : [];
const dateFrom = String(query.date_from || "").trim();
const dateTo = String(query.date_to || "").trim();

if (!/^\d{4}-\d{2}-\d{2}$/.test(dateFrom) || !/^\d{4}-\d{2}-\d{2}$/.test(dateTo) || dateFrom > dateTo) {
  return fail(400, "DATE_RANGE_INVALID");
}

const initData = headers["x-telegram-init-data"] || headers["X-Telegram-Init-Data"] || query.initData || query.init_data || null;
if (!initData) return fail(401, "INIT_DATA_MISSING");

const botToken = $env.MONEYTRACK_BOT_TOKEN;
if (!botToken) return fail(500, "BOT_TOKEN_MISSING");

const params = {};
try {
  for (const part of initData.split("&")) {
    const eq = part.indexOf("=");
    if (eq === -1) continue;
    params[decodeURIComponent(part.slice(0, eq))] = decodeURIComponent(part.slice(eq + 1));
  }
} catch {
  return fail(401, "INVALID_INIT_DATA");
}

const receivedHash = params.hash;
if (!receivedHash) return fail(401, "HASH_MISSING");
delete params.hash;

const dataCheckString = Object.keys(params).sort().map((key) => `${key}=${params[key]}`).join("\n");
const secretKey = crypto.createHmac("sha256", "WebAppData").update(botToken).digest();
const calculatedHash = crypto.createHmac("sha256", secretKey).update(dataCheckString).digest("hex");
if (calculatedHash !== receivedHash) return fail(401, "INVALID_INIT_DATA_HASH");
if (!params.user) return fail(401, "USER_MISSING");

let user;
try { user = JSON.parse(params.user); } catch { return fail(401, "INVALID_USER_DATA"); }
if (!user?.id) return fail(401, "INVALID_USER_DATA");

return [{ json: { ok: true, telegram_user_id: user.id, excluded_account_ids: excludedIds, excluded_sql: excludedIds.join(","), date_from: dateFrom, date_to: dateTo } }];

const row = $input.first().json || {};

if (!row.user_id) return [{ json: { ok: false, http_status: 404, error: "USER_NOT_FOUND" } }];

return [{
  json: {
    ok: true,
    data: {
      base_currency: row.base_currency,
      total_base: Number(row.total_base || 0),
      included_account_count: Number(row.included_account_count || 0),
      excluded_account_ids: $("Validate Explorer Summary Request").first().json.excluded_account_ids || [],
      snapshot_date: row.date_to,
      snapshot_missing_rate_count: Number(row.snapshot_missing_rate_count || 0),
      account_balances: (row.account_balances || []).map((item) => ({
        account_id: item.account_id,
        parent_id: item.parent_id,
        currency_code: item.currency_code,
        is_leaf: item.is_leaf === true || item.is_leaf === "true",
        balance_original: Number(item.balance_original || 0),
        balance_base: item.balance_base == null ? null : Number(item.balance_base)
      })),
      period: { date_from: row.date_from, date_to: row.date_to },
      period_summary: {
        income: Number(row.period_income || 0),
        expense: Number(row.period_expense || 0),
        result: Number(row.period_result || 0),
        missing_rate_count: Number(row.period_missing_rate_count || 0)
      }
    }
  }
}];
